// 1. Define Weights
const weights = {
  correctness_topical: 0.42,
  coherence_logical: 0.28,
  coherence_stylistic: 0.32,
  coverage_broad: 0.37,
  coverage_deep: 0.39,
  consistency_internal: 0.39
};

const THRESHOLD = 0.1;

// 2. Merge all incoming items into one single object
// This takes the fragmented list and combines them
let mergedData = {};
let scoreA = 0;
let scoreB = 0;

for (const item of $input.all()) {
  const data = item.json;

  // Merge the JSON properties into our master object
  Object.assign(mergedData, data);

  // Calculate scores on the fly
  for (const [dimension, weight] of Object.entries(weights)) {
    // We check if this specific item contains the dimension we are looking for
    if (data[dimension] && data[dimension].agent_winner) {
      const winner = data[dimension].agent_winner.toLowerCase();
      if (winner === 'a') scoreA += weight;
      else if (winner === 'b') scoreB += weight;
    }
  }
}

// 3. Remove any partial/old 'quality_overall' that might have come in from previous steps
if (mergedData.quality_overall) {
  delete mergedData.quality_overall;
}

// 4. Determine Overall Winner based on TOTAL sums
let overallWinner = 'n';
const diff = Math.abs(scoreA - scoreB);

if (diff > THRESHOLD) {
  overallWinner = scoreA > scoreB ? 'a' : 'b';
}

// 5. Construct the final single object
// We return an array containing just ONE item (the merged result)
return [
  {
    json: {
      ...mergedData, // Spread all the dimension keys (Correctness, Coherence, etc.) first
      quality_overall: { // Add the calculated overall result LAST
        agent_winner: overallWinner,
        score_a: Number(scoreA.toFixed(2)),
        score_b: Number(scoreB.toFixed(2)),
      }
    }
  }
];

