// Loop through the main input items (usually 1 item containing the webhook data)
for (const item of $input.all()) {

  // Access the 'body' array where your data lives
  const bodyItems = item.json.body;

  if (Array.isArray(bodyItems)) {

    // Loop through each item inside the 'body' array
    for (const data of bodyItems) {

      // Iterate over keys like "correctness_topical", "coherence_logical", etc.
      Object.keys(data).forEach(key => {
        const category = data[key];

        // Check if it is an object to avoid primitive fields like "query"
        if (category && typeof category === 'object') {

          // 1. Remove "grade"
          if ('grade' in category) {
            delete category.grade;
          }

          // 2. Remove severity fields from "judgement_details"
          if (Array.isArray(category.judgement_details)) {
            category.judgement_details.forEach(detail => {
              delete detail.severity;
              delete detail.severity_level;
              delete detail.penalty_value;
            });
          }
        }
      });
    }
  }
}

// Return the items exactly as they came in, just cleaned
return $input.all();

